-- ===== 0001_timestamptz (sha256 9d63ae0a9a2c36aa77b24ef4ac881ca2b693e2624e1950fabccef609f236db51) =====
-- 0001_timestamptz: every timestamp column becomes timestamptz, and the database time zone becomes UTC.
--
-- Why. The v0.1.0 columns were `timestamp without time zone`. DEFAULT now() stored the wall clock of the PostgreSQL session zone,
-- the application stored the UTC wall clock of a JavaScript Date, and drizzle read both back as UTC: on a machine whose zone is not
-- UTC (Cairo: +2/+3 h) the two kinds of value differed by the zone offset, and a backup/restore moved them again by the offset of
-- the machine that ran it. A timestamptz is an absolute instant; neither the session zone nor the client zone can change it.
--
-- Rule for existing values: a naive value is read as UTC, which is exactly how the application has always displayed it, so every
-- value reads back the same instant it showed before the migration. Values that v0.1.0 wrote through DEFAULT now() on a database
-- whose zone was not UTC keep the offset they always had; audit_trail.timestamp_str (the value the hash chain covers) is untouched.
--
-- Append-only tables (audit_trail, signatures): this is a column type change, not an UPDATE; the row triggers do not fire, no
-- value of the hash chain or of a signature changes, and the migration adds no row to them (the runner appends its own audit entry).

ALTER TABLE "audit_trail"
  ALTER COLUMN "timestamp" DROP DEFAULT,
  ALTER COLUMN "timestamp" TYPE timestamp with time zone USING "timestamp" AT TIME ZONE 'UTC',
  ALTER COLUMN "timestamp" SET DEFAULT now();

ALTER TABLE "batch_materials"
  ALTER COLUMN "dispensed_at" DROP DEFAULT,
  ALTER COLUMN "dispensed_at" TYPE timestamp with time zone USING "dispensed_at" AT TIME ZONE 'UTC',
  ALTER COLUMN "dispensed_at" SET DEFAULT now();

ALTER TABLE "batch_releases"
  ALTER COLUMN "released_at" TYPE timestamp with time zone USING "released_at" AT TIME ZONE 'UTC';

ALTER TABLE "jobs"
  ALTER COLUMN "created_at" DROP DEFAULT,
  ALTER COLUMN "created_at" TYPE timestamp with time zone USING "created_at" AT TIME ZONE 'UTC',
  ALTER COLUMN "created_at" SET DEFAULT now(),
  ALTER COLUMN "updated_at" DROP DEFAULT,
  ALTER COLUMN "updated_at" TYPE timestamp with time zone USING "updated_at" AT TIME ZONE 'UTC',
  ALTER COLUMN "updated_at" SET DEFAULT now();

ALTER TABLE "lab_notebook"
  ALTER COLUMN "entered_at" DROP DEFAULT,
  ALTER COLUMN "entered_at" TYPE timestamp with time zone USING "entered_at" AT TIME ZONE 'UTC',
  ALTER COLUMN "entered_at" SET DEFAULT now(),
  ALTER COLUMN "signed_at" TYPE timestamp with time zone USING "signed_at" AT TIME ZONE 'UTC';

ALTER TABLE "results"
  ALTER COLUMN "entered_at" TYPE timestamp with time zone USING "entered_at" AT TIME ZONE 'UTC';

ALTER TABLE "samples"
  ALTER COLUMN "created_at" DROP DEFAULT,
  ALTER COLUMN "created_at" TYPE timestamp with time zone USING "created_at" AT TIME ZONE 'UTC',
  ALTER COLUMN "created_at" SET DEFAULT now();

ALTER TABLE "signatures"
  ALTER COLUMN "timestamp" DROP DEFAULT,
  ALTER COLUMN "timestamp" TYPE timestamp with time zone USING "timestamp" AT TIME ZONE 'UTC',
  ALTER COLUMN "timestamp" SET DEFAULT now();

ALTER TABLE "system_settings"
  ALTER COLUMN "updated_at" DROP DEFAULT,
  ALTER COLUMN "updated_at" TYPE timestamp with time zone USING "updated_at" AT TIME ZONE 'UTC',
  ALTER COLUMN "updated_at" SET DEFAULT now();

ALTER TABLE "training_records"
  ALTER COLUMN "completed_at" TYPE timestamp with time zone USING "completed_at" AT TIME ZONE 'UTC';

ALTER TABLE "users"
  ALTER COLUMN "password_changed_at" DROP DEFAULT,
  ALTER COLUMN "password_changed_at" TYPE timestamp with time zone USING "password_changed_at" AT TIME ZONE 'UTC',
  ALTER COLUMN "password_changed_at" SET DEFAULT now(),
  ALTER COLUMN "locked_at" TYPE timestamp with time zone USING "locked_at" AT TIME ZONE 'UTC',
  ALTER COLUMN "created_at" DROP DEFAULT,
  ALTER COLUMN "created_at" TYPE timestamp with time zone USING "created_at" AT TIME ZONE 'UTC',
  ALTER COLUMN "created_at" SET DEFAULT now();

-- Database default zone. The application also forces UTC on every connection it opens (src/db/index.ts), so this only matters
-- for other clients (psql, reports); if the role may not change the database setting, say so loudly instead of failing the upgrade.
DO $$
BEGIN
  EXECUTE format('ALTER DATABASE %I SET timezone TO %L', current_database(), 'UTC');
EXCEPTION WHEN insufficient_privilege THEN
  RAISE WARNING 'Could not set the default time zone of database % to UTC (insufficient privilege). Timestamps are unaffected; ask a database owner to run: ALTER DATABASE % SET timezone TO ''UTC''', current_database(), current_database();
END
$$;

-- ===== 0002_counters (sha256 1389f361d92c94d9665af61f8095be5895e12fa741f570af17f900c64a347821) =====
-- 0002_counters: gap-free counters behind nextSequence(tx, key) (src/server/core/tx.ts).
--
-- Sample numbers were COUNT(*)+1 (two concurrent registrations collided on the primary key, and the number never restarted each
-- year). The sample numbering moves to one counter row per year, key 'sample:<year>'. Installations that already hold samples
-- start each counter at the highest number in use, so the first number issued after the upgrade is unused.

CREATE TABLE "counters" (
	"key" text PRIMARY KEY NOT NULL,
	"value" bigint NOT NULL
);

INSERT INTO "counters" ("key", "value")
SELECT 'sample:' || split_part("id", '-', 2), max(split_part("id", '-', 3)::bigint)
FROM "samples"
WHERE "id" ~ '^SMP-[0-9]{4}-[0-9]+$'
GROUP BY split_part("id", '-', 2);

-- ===== 0003_indexes (sha256 96cfd71cd806ee4c5772dc4703779febab39ab8d476b97c48eeb6d5adb9b2603) =====
-- 0003_indexes: the secondary indexes the application's queries need. v0.1.0 had none beyond the primary keys, and PostgreSQL
-- does not index foreign keys, so every "results of this sample", "signatures of this sample" and "samples of this batch" was a scan.
--
-- Each index below serves a query that exists today:
--   results(sample_id)                      sample detail, CoA/PDF, batch report, traceability, transition checks
--   signatures(sample_id, timestamp)        sample detail and ELN (newest signature first), batch report
--   samples(batch)                          batch release, batch report, traceability
--   samples(material)                       reports filter and spec lookup by material
--   samples(state)                          dashboard and list filters
--   samples(created_at)                     sample list (newest first) and trend reports
--   oos_investigations(sample_id, status)   "open investigation for this sample" gate in batch release
--   oos_investigations(result_id)           investigation of a result
--   lab_notebook(sample_id, entered_at)     notebook entries of a sample, oldest first
--   batch_materials(batch)                  batch traceability
--   training_records(user_id)               a user's training records
--   specifications(material, status)        "the Active specification of this material" on every registration
--   audit_trail(entity, entity_id)          the history of one record
--   audit_trail(user_id)                    what one user did

CREATE INDEX "results_sample_id_idx" ON "results" USING btree ("sample_id");
CREATE INDEX "signatures_sample_id_timestamp_idx" ON "signatures" USING btree ("sample_id","timestamp");
CREATE INDEX "samples_batch_idx" ON "samples" USING btree ("batch");
CREATE INDEX "samples_material_idx" ON "samples" USING btree ("material");
CREATE INDEX "samples_state_idx" ON "samples" USING btree ("state");
CREATE INDEX "samples_created_at_idx" ON "samples" USING btree ("created_at");
CREATE INDEX "oos_investigations_sample_id_status_idx" ON "oos_investigations" USING btree ("sample_id","status");
CREATE INDEX "oos_investigations_result_id_idx" ON "oos_investigations" USING btree ("result_id");
CREATE INDEX "lab_notebook_sample_id_entered_at_idx" ON "lab_notebook" USING btree ("sample_id","entered_at");
CREATE INDEX "batch_materials_batch_idx" ON "batch_materials" USING btree ("batch");
CREATE INDEX "training_records_user_id_idx" ON "training_records" USING btree ("user_id");
CREATE INDEX "specifications_material_status_idx" ON "specifications" USING btree ("material","status");
CREATE INDEX "audit_trail_entity_idx" ON "audit_trail" USING btree ("entity","entity_id");
CREATE INDEX "audit_trail_user_id_idx" ON "audit_trail" USING btree ("user_id");

-- ===== 0010_identity (sha256 38894921094277b4b4303236f5be892536cb19710befef6ddea12f6c6e2b8b0e) =====
-- 0010_identity: identity and authentication (roadmap M05) and controlled AI egress (roadmap M16).
--
-- What this adds, and why:
--   users                  must_change_password   first sign-in and administrator reset force a new password
--                          login_failed_attempts, login_locked_until
--                                                 the SIGN-IN lockout, separate from failed_attempts / locked_at, which stay the SIGNING lockout:
--                                                 a lock set by wrong e-signature passwords used to block sign-in for ever (login rejected any non-null locked_at)
--                          totp_pending_secret    enrolment in progress (ciphertext, like totp_secret)
--                          totp_last_step         newest accepted TOTP step: the replay guard
--                          totp_enrolled_at, version
--                          lower(email) is unique (no two accounts differing only in case)
--   system_settings        password_history_count, lockout_minutes, mfa_required, session_absolute_hours, version
--   sessions               one row per sign-in; idle and absolute timeout, logout and revocation are decided from it
--   password_history       the hashes behind "not one of the last N passwords"
--   auth_challenges        single-use second-step challenges (MFA, enrolment)
--   recovery_codes         one-time MFA recovery codes (salted scrypt hashes)
--   integration_settings   external AI switch (off by default) and the encrypted API key
--
-- Existing rows: every new column has a default that keeps today's behaviour; the current password hash of each user becomes the first
-- password_history row. Plaintext TOTP secrets already in users.totp_secret are not touched here (SQL has no access to the key); the
-- application reads them and rewrites them as ciphertext the first time they are used, and `admin-cli rotate-keys` rewrites any that remain.
-- Nothing here rewrites audit_trail or signatures.

DO $$
BEGIN
  IF EXISTS (SELECT 1 FROM users WHERE email IS NOT NULL GROUP BY lower(email) HAVING count(*) > 1) THEN
    RAISE EXCEPTION '0010_identity: two users share an e-mail address that differs only in letter case. Correct one of them, then run the migration again.';
  END IF;
END $$;

