-- ===== 0050_results_oos (sha256 f83066a99b023fcc48036e0c44c3f99c8670e1da5707497cb0588ce82576c46a) =====
-- 0050_results_oos (roadmap M10): results are judged against the limit they were registered with, a sample keeps the
-- specification revision it was registered under, and an OOS investigation has a phase, a decision and one open record per result.
--
-- Why: v0.1.0 judged a result with parseFloat against spec_min / spec_max, which are `real` (0.005 reads back as 0.004999999888) and
-- carry no limit kind and no declared decimals, so USP 7.20 rounding was impossible; registration took "the" Active specification
-- of the material and kept no reference to it; nothing stopped two open investigations for one result (21 CFR 211.192, 211.194;
-- Annex 11 s.5 data, s.6 accuracy checks).
--
-- What this adds (all additive and nullable; no existing row is changed, the columns the signature hashes cover are untouched):
--   results.unit, limit_kind, lower_text, upper_text, decimals, acceptance_text
--                       the limit copied from the specification revision at registration, limits as decimal text. NULL on rows written
--                       before this migration: the evaluator then reads spec_min / spec_max and compares without rounding.
--   samples.spec_id -> specifications(id), samples.spec_revision
--                       the revision the sample is tested against. NULL on samples registered before this migration.
--   oos_investigations.phase, decision
--                       Phase I | Phase II | Pending QA while open; the outcome QA signs on closure. NULL on old rows.
--   oos_investigations_one_open_per_result_uidx
--                       at most one investigation per result that is not Closed (or v0.1.0's Approved).
--
-- audit_trail and signatures are not touched.

ALTER TABLE "results" ADD COLUMN "unit" text;
ALTER TABLE "results" ADD COLUMN "limit_kind" text;
ALTER TABLE "results" ADD COLUMN "lower_text" text;
ALTER TABLE "results" ADD COLUMN "upper_text" text;
ALTER TABLE "results" ADD COLUMN "decimals" integer;
ALTER TABLE "results" ADD COLUMN "acceptance_text" text;

ALTER TABLE "samples" ADD COLUMN "spec_id" text;
ALTER TABLE "samples" ADD COLUMN "spec_revision" integer;
ALTER TABLE "samples" ADD CONSTRAINT "samples_spec_id_specifications_id_fk" FOREIGN KEY ("spec_id") REFERENCES "public"."specifications"("id") ON DELETE no action ON UPDATE no action;
CREATE INDEX "samples_spec_id_idx" ON "samples" USING btree ("spec_id");

ALTER TABLE "oos_investigations" ADD COLUMN "phase" text;
ALTER TABLE "oos_investigations" ADD COLUMN "decision" text;
CREATE UNIQUE INDEX "oos_investigations_one_open_per_result_uidx" ON "oos_investigations" USING btree ("result_id") WHERE "oos_investigations"."status" NOT IN ('Closed', 'Approved');

-- ===== 0060_spec (sha256 a4827dec6d8be0d9a71cae4f7d2ac0546cac5efc07df150deff0b57650ae942e) =====
-- 0060_spec (roadmap M11): the revision of a specification is not the optimistic-concurrency counter, and a specification has an author.
--
-- Why: specifications.version was both. The create form let the user type it, every edit added 1 and the approval added 1 more, so a
-- first revision edited once and approved showed "v3". Nothing recorded who wrote a specification, so nothing could stop the author
-- from approving it (21 CFR 211.160, 211.165 master data; Annex 11 s.12 segregation of duties).
--
-- What this adds to specifications (all additive; version, status, effective_date and parameters are not touched):
--   revision_label  integer NOT NULL DEFAULT 1   the revision, per material, assigned by the server. Existing rows are numbered per
--                                                material in the order they take effect: effective date, then the order the audit
--                                                trail saw them created, then id. (The ties and the unaudited rows are the only place
--                                                a judgement is made; the numbering is a label, not a record: nothing signed covers it.)
--   created_by      text -> users(id), nullable   the author, read from the first Create entry of the audit trail. Null where the
--                                                installation never audited the creation (the demo seed): such a row is already Active.
--   approved_by     text -> users(id), nullable   the approver, read from the latest Approve entry, for Active and Obsolete rows only.
-- and the unique index (material, revision_label): two revisions of one material cannot share a number, whatever the application does.
--
-- audit_trail and signatures are only read here. The migration writes no row of either.

ALTER TABLE "specifications" ADD COLUMN "revision_label" integer DEFAULT 1 NOT NULL;
ALTER TABLE "specifications" ADD COLUMN "created_by" text;
ALTER TABLE "specifications" ADD COLUMN "approved_by" text;

UPDATE "specifications" s SET "revision_label" = ranked.rev
FROM (
	SELECT sp.id,
		row_number() OVER (PARTITION BY sp.material ORDER BY sp.effective_date, created.first_sequence NULLS LAST, sp.id) AS rev
	FROM "specifications" sp
	LEFT JOIN LATERAL (
		SELECT min(a."sequence") AS first_sequence
		FROM "audit_trail" a
		WHERE a.entity = 'Specification' AND a.entity_id = sp.id AND a.action = 'Create'
	) created ON true
) ranked
WHERE ranked.id = s.id;

UPDATE "specifications" s SET "created_by" = a.user_id
FROM (
	SELECT DISTINCT ON (entity_id) entity_id, user_id
	FROM "audit_trail"
	WHERE entity = 'Specification' AND action = 'Create'
	ORDER BY entity_id, "sequence" ASC
) a
WHERE a.entity_id = s.id AND EXISTS (SELECT 1 FROM "users" u WHERE u.id = a.user_id);

UPDATE "specifications" s SET "approved_by" = a.user_id
FROM (
	SELECT DISTINCT ON (entity_id) entity_id, user_id
	FROM "audit_trail"
	WHERE entity = 'Specification' AND action = 'Approve'
	ORDER BY entity_id, "sequence" DESC
) a
WHERE a.entity_id = s.id AND s.status IN ('Active', 'Obsolete') AND EXISTS (SELECT 1 FROM "users" u WHERE u.id = a.user_id);

CREATE UNIQUE INDEX "specifications_material_revision_uq" ON "specifications" USING btree ("material","revision_label");
ALTER TABLE "specifications" ADD CONSTRAINT "specifications_created_by_users_id_fk" FOREIGN KEY ("created_by") REFERENCES "public"."users"("id") ON DELETE no action ON UPDATE no action;
ALTER TABLE "specifications" ADD CONSTRAINT "specifications_approved_by_users_id_fk" FOREIGN KEY ("approved_by") REFERENCES "public"."users"("id") ON DELETE no action ON UPDATE no action;
CREATE INDEX "specifications_created_by_idx" ON "specifications" USING btree ("created_by");
CREATE INDEX "specifications_approved_by_idx" ON "specifications" USING btree ("approved_by");

-- ===== 0070_quality (sha256 59fb1e389ca2e19dd127a53352ff82ed1b60d383eb19baed3eabec1bec799753) =====
-- 0070_quality: calibration history, environmental limits and excursions, a version on instruments, the VERIFICATION meaning
-- (roadmap M13, r1-quality-fixes).
--
-- instruments          + version (optimistic concurrency, and the record version a calibration signature is bound to).
-- calibration_history  One row per signed calibration: who, when, the due date before and after, the status before and after,
--                      the instrument version it produced and the reason. Append-only (UPDATE, DELETE and TRUNCATE are refused by
--                      the triggers below, which use the shared refusal function of src/db/protections/common.ts).
-- env_limits           Environmental monitoring limits per cleanroom grade and sample type: the alert limit (optional, the site
--                      sets it from its own trend data) and the action limit. Site data, not code: QA approves and edits the rows.
-- env_records          + sample_type, and the limits the record was judged against (limit_alert, limit_action), so a later edit of
--                      the limits table does not change what an old result was compared with.
-- env_excursions       One row per action-level result: opened in the same transaction as the record, never closed by an edit of
--                      the count (closing it is an investigation decision, not a recount).
-- signature_meanings   + VERIFICATION: a second person verifies what someone else recorded (a dispensing against its CoA).
--
-- Seeded rows (env_limits, signature_meanings) are written only under the migration runner (WHERE EXISTS schema_migrations),
-- like 0020 and 0040: a restore replays this file into an empty database and then loads the rows of the backup.
--
-- The env_limits seed is the example table the roadmap gives for EU GMP Annex 1 (2022): maximum action limits for viable
-- particles, Grade A "no growth" (stored as 0: any count above 0 is an action-level result), no alert limits. They are examples:
-- approved_by is NULL until the site's QA approves its own limits, and the source column says so.
--
-- Existing rows: nothing is rewritten. Instruments start at version 1; environmental records keep their status text (a v0.1.0
-- record may say 'Action Level' or carry the grade 'A') and have no sample type until a QA edit gives them one.

ALTER TABLE "instruments" ADD COLUMN "version" integer DEFAULT 1 NOT NULL;

CREATE TABLE "calibration_history" (
	"id" text PRIMARY KEY NOT NULL,
	"instrument_id" text NOT NULL,
	"performed_by" text NOT NULL,
	"performed_at" timestamp with time zone DEFAULT now() NOT NULL,
	"previous_due_date" text NOT NULL,
	"new_due_date" text NOT NULL,
	"status_before" text NOT NULL,
	"status_after" text NOT NULL,
	"instrument_version" integer NOT NULL,
	"reason" text NOT NULL
);

ALTER TABLE "calibration_history" ADD CONSTRAINT "calibration_history_instrument_id_instruments_id_fk" FOREIGN KEY ("instrument_id") REFERENCES "public"."instruments"("id") ON DELETE no action ON UPDATE no action;
ALTER TABLE "calibration_history" ADD CONSTRAINT "calibration_history_performed_by_users_id_fk" FOREIGN KEY ("performed_by") REFERENCES "public"."users"("id") ON DELETE no action ON UPDATE no action;
CREATE UNIQUE INDEX "calibration_history_instrument_version_uidx" ON "calibration_history" USING btree ("instrument_id","instrument_version");
CREATE INDEX "calibration_history_performed_by_idx" ON "calibration_history" USING btree ("performed_by");

CREATE OR REPLACE FUNCTION gxp_block_mutation() RETURNS trigger AS $$
    BEGIN
      RAISE EXCEPTION 'GxP: % on % is not permitted (append-only record)', TG_OP, TG_TABLE_NAME
        USING ERRCODE = 'integrity_constraint_violation';
    END;
    $$ LANGUAGE plpgsql;
CREATE TRIGGER gxp_calibration_history_row_guard BEFORE UPDATE OR DELETE ON calibration_history FOR EACH ROW EXECUTE FUNCTION gxp_block_mutation();
CREATE TRIGGER gxp_calibration_history_truncate_guard BEFORE TRUNCATE ON calibration_history FOR EACH STATEMENT EXECUTE FUNCTION gxp_block_mutation();

CREATE TABLE "env_limits" (
	"id" text PRIMARY KEY NOT NULL,
	"grade" text NOT NULL,
	"sample_type" text NOT NULL,
	"unit" text NOT NULL,
	"alert_limit" integer,
	"action_limit" integer NOT NULL,
	"source" text NOT NULL,
	"approved_by" text,
	"approved_at" timestamp with time zone,
	"active" boolean DEFAULT true NOT NULL,
	"version" integer DEFAULT 1 NOT NULL
);

ALTER TABLE "env_limits" ADD CONSTRAINT "env_limits_approved_by_users_id_fk" FOREIGN KEY ("approved_by") REFERENCES "public"."users"("id") ON DELETE no action ON UPDATE no action;
CREATE UNIQUE INDEX "env_limits_active_uidx" ON "env_limits" USING btree ("grade","sample_type") WHERE "env_limits"."active";

ALTER TABLE "env_records" ADD COLUMN "sample_type" text;
ALTER TABLE "env_records" ADD COLUMN "limit_alert" integer;
ALTER TABLE "env_records" ADD COLUMN "limit_action" integer;

CREATE TABLE "env_excursions" (
	"id" text PRIMARY KEY NOT NULL,
	"env_record_id" text NOT NULL,
	"level" text NOT NULL,
	"grade" text NOT NULL,
	"sample_type" text NOT NULL,
	"viable_count" integer NOT NULL,
	"limit_value" integer NOT NULL,
	"status" text DEFAULT 'Open' NOT NULL,
	"opened_by" text NOT NULL,
	"opened_at" timestamp with time zone DEFAULT now() NOT NULL,
	"version" integer DEFAULT 1 NOT NULL
);

ALTER TABLE "env_excursions" ADD CONSTRAINT "env_excursions_env_record_id_env_records_id_fk" FOREIGN KEY ("env_record_id") REFERENCES "public"."env_records"("id") ON DELETE no action ON UPDATE no action;
ALTER TABLE "env_excursions" ADD CONSTRAINT "env_excursions_opened_by_users_id_fk" FOREIGN KEY ("opened_by") REFERENCES "public"."users"("id") ON DELETE no action ON UPDATE no action;
CREATE INDEX "env_excursions_env_record_id_idx" ON "env_excursions" USING btree ("env_record_id");
CREATE INDEX "env_excursions_opened_by_idx" ON "env_excursions" USING btree ("opened_by");

INSERT INTO "env_limits" ("id", "grade", "sample_type", "unit", "alert_limit", "action_limit", "source")
