ALTER TABLE "instrument_import_rows" ADD CONSTRAINT "instrument_import_rows_decided_by_users_id_fk" FOREIGN KEY ("decided_by") REFERENCES "public"."users"("id") ON DELETE no action ON UPDATE no action;
