-- ===== 0320_spc (sha256 7cfdb024401d59fc512639f2ef62b62b98e7ec466564dc7f21d49e56f130844e) =====
-- 0320_spc: statistical process control, out-of-trend alerts and stability shelf-life trending (roadmap M39, r3-spc).
--
-- What this adds, and why:
--   spc_baselines   the control limits of one attribute (product + parameter): individuals-chart centre line, MRbar, sigma, UCL, LCL,
--                   computed by the server from the approved results of a window, with the ids of the points used, every exclusion
--                   (named and justified) and a hash of the values, so the limits are reproducible. Versioned (revision); an Approved
--                   baseline is replaced by a new revision, never edited. Signed with SPC_BASELINE_APPROVAL.
--   spc_alerts      an out-of-trend finding: a rule of the baseline's rule set violated by an approved result entered after the
--                   baseline's data window. ADVISORY: it never changes a result, a specification or a disposition. Open, then
--                   Acknowledged by QA with a note. One alert per (baseline, result, rule).
--   signature_meanings  + SPC_BASELINE_APPROVAL (QA, Admin; a reason is required).
--   permissions     spc.view (every role) and spc.manage (QA, Admin: set a baseline, evaluate, acknowledge), positions 320 and 321.
--
-- The results, samples and stability tables are not altered. The constants are written only under the migration runner (WHERE EXISTS
-- schema_migrations), like 0240 and 0300, because a restore replays this file into an EMPTY database and then loads the backed-up rows.

CREATE TABLE "spc_alerts" (
	"id" text PRIMARY KEY NOT NULL,
	"baseline_id" text NOT NULL,
	"product_id" text NOT NULL,
	"parameter" text NOT NULL,
	"result_id" text NOT NULL,
	"sample_id" text NOT NULL,
	"batch" text NOT NULL,
	"rule" text NOT NULL,
	"severity" text NOT NULL,
	"value" double precision NOT NULL,
	"z" double precision NOT NULL,
	"detail" text NOT NULL,
	"status" text DEFAULT 'Open' NOT NULL,
	"detected_by" text NOT NULL,
	"detected_at" timestamp with time zone DEFAULT now() NOT NULL,
	"acknowledged_by" text,
	"acknowledged_at" timestamp with time zone,
	"acknowledgement" text,
	"version" integer DEFAULT 1 NOT NULL,
	CONSTRAINT "spc_alerts_status_check" CHECK ("spc_alerts"."status" IN ('Open', 'Acknowledged')),
	CONSTRAINT "spc_alerts_severity_check" CHECK ("spc_alerts"."severity" IN ('warning', 'violation'))
);

CREATE TABLE "spc_baselines" (
	"id" text PRIMARY KEY NOT NULL,
	"product_id" text NOT NULL,
	"parameter" text NOT NULL,
	"revision" integer NOT NULL,
	"status" text DEFAULT 'Approved' NOT NULL,
	"rule_set" text NOT NULL,
	"n" integer NOT NULL,
	"cl" double precision NOT NULL,
	"mr_bar" double precision NOT NULL,
	"sigma" double precision NOT NULL,
	"ucl" double precision NOT NULL,
	"lcl" double precision NOT NULL,
	"data_from" timestamp with time zone NOT NULL,
	"data_to" timestamp with time zone NOT NULL,
	"result_ids" jsonb NOT NULL,
	"exclusions" jsonb NOT NULL,
	"data_hash" text NOT NULL,
	"reason" text NOT NULL,
	"created_by" text NOT NULL,
	"created_at" timestamp with time zone DEFAULT now() NOT NULL,
	"version" integer DEFAULT 1 NOT NULL,
	CONSTRAINT "spc_baselines_status_check" CHECK ("spc_baselines"."status" IN ('Approved', 'Superseded')),
	CONSTRAINT "spc_baselines_rule_set_check" CHECK ("spc_baselines"."rule_set" IN ('nelson', 'westgard')),
	CONSTRAINT "spc_baselines_n_check" CHECK ("spc_baselines"."n" >= 2),
	CONSTRAINT "spc_baselines_reason_check" CHECK (length(btrim("spc_baselines"."reason")) >= 5)
);

ALTER TABLE "spc_alerts" ADD CONSTRAINT "spc_alerts_baseline_id_spc_baselines_id_fk" FOREIGN KEY ("baseline_id") REFERENCES "public"."spc_baselines"("id") ON DELETE no action ON UPDATE no action;
ALTER TABLE "spc_alerts" ADD CONSTRAINT "spc_alerts_product_id_products_id_fk" FOREIGN KEY ("product_id") REFERENCES "public"."products"("id") ON DELETE no action ON UPDATE no action;
ALTER TABLE "spc_alerts" ADD CONSTRAINT "spc_alerts_result_id_results_id_fk" FOREIGN KEY ("result_id") REFERENCES "public"."results"("id") ON DELETE no action ON UPDATE no action;
ALTER TABLE "spc_alerts" ADD CONSTRAINT "spc_alerts_sample_id_samples_id_fk" FOREIGN KEY ("sample_id") REFERENCES "public"."samples"("id") ON DELETE no action ON UPDATE no action;
ALTER TABLE "spc_alerts" ADD CONSTRAINT "spc_alerts_detected_by_users_id_fk" FOREIGN KEY ("detected_by") REFERENCES "public"."users"("id") ON DELETE no action ON UPDATE no action;
ALTER TABLE "spc_alerts" ADD CONSTRAINT "spc_alerts_acknowledged_by_users_id_fk" FOREIGN KEY ("acknowledged_by") REFERENCES "public"."users"("id") ON DELETE no action ON UPDATE no action;
ALTER TABLE "spc_baselines" ADD CONSTRAINT "spc_baselines_product_id_products_id_fk" FOREIGN KEY ("product_id") REFERENCES "public"."products"("id") ON DELETE no action ON UPDATE no action;
ALTER TABLE "spc_baselines" ADD CONSTRAINT "spc_baselines_created_by_users_id_fk" FOREIGN KEY ("created_by") REFERENCES "public"."users"("id") ON DELETE no action ON UPDATE no action;
CREATE UNIQUE INDEX "spc_alerts_finding_uidx" ON "spc_alerts" USING btree ("baseline_id","result_id","rule");
CREATE INDEX "spc_alerts_status_idx" ON "spc_alerts" USING btree ("status","detected_at");
CREATE INDEX "spc_alerts_product_id_idx" ON "spc_alerts" USING btree ("product_id");
CREATE INDEX "spc_alerts_result_id_idx" ON "spc_alerts" USING btree ("result_id");
CREATE INDEX "spc_alerts_sample_id_idx" ON "spc_alerts" USING btree ("sample_id");
CREATE INDEX "spc_alerts_detected_by_idx" ON "spc_alerts" USING btree ("detected_by");
CREATE INDEX "spc_alerts_acknowledged_by_idx" ON "spc_alerts" USING btree ("acknowledged_by");
CREATE UNIQUE INDEX "spc_baselines_revision_uidx" ON "spc_baselines" USING btree ("product_id","parameter","revision");
CREATE UNIQUE INDEX "spc_baselines_one_approved_uidx" ON "spc_baselines" USING btree ("product_id","parameter") WHERE "spc_baselines"."status" = 'Approved';
CREATE INDEX "spc_baselines_created_by_idx" ON "spc_baselines" USING btree ("created_by");

-- ---- constants (only under the migration runner) ------------------------------------------------------------------------------

INSERT INTO "signature_meanings" ("code", "text", "allowed_roles", "requires_reason", "training_exempt")
SELECT v.* FROM (VALUES
	('SPC_BASELINE_APPROVAL', 'Control limit baseline approval: I have reviewed the data, the exclusions and the computed limits, and approve them as the reference for trending this attribute.', ARRAY['QA', 'Admin'], true, false)
) AS v(code, text, allowed_roles, requires_reason, training_exempt)
WHERE EXISTS (SELECT 1 FROM "schema_migrations");

INSERT INTO "permissions" ("code", "category", "description", "position")
SELECT v.* FROM (VALUES
	('spc.view', 'Trending', 'Read control charts, baselines, out-of-trend alerts and shelf-life estimates', 320),
	('spc.manage', 'Trending', 'Set a control-limit baseline (e-signed), evaluate and acknowledge out-of-trend alerts', 321)
) AS v("code", "category", "description", "position")
WHERE EXISTS (SELECT 1 FROM "schema_migrations");

INSERT INTO "role_permissions" ("id", "role_id", "permission_code")
SELECT v."role_id" || ':' || v."permission_code", v."role_id", v."permission_code" FROM (VALUES
	('role-admin', 'spc.view'), ('role-admin', 'spc.manage'),
	('role-qa', 'spc.view'), ('role-qa', 'spc.manage'),
	('role-reviewer', 'spc.view'),
	('role-analyst', 'spc.view')
) AS v("role_id", "permission_code")
WHERE EXISTS (SELECT 1 FROM "schema_migrations");

-- ===== 0330_periodic_archive (sha256 24c9e412db7ffc3b98f69ae670986aa3a404755def5ecc9983842d1f19e307df) =====
-- 0330_periodic_archive: periodic review, retention policies and legal hold, and verifiable batch archives
-- (roadmap M42, r3-periodic-archive; EU GMP Annex 11 sections 11 and 17, 21 CFR 211.180, 21 CFR Part 11.10(c)).
--
-- What this adds, and why:
--   periodic_review_plans   what is reviewed, how often and when it is next due: one Active plan per (kind, subject). Kinds: user_access,
--                           instrument, specification, method, document, module, system. The checklist is the plan's template.
--   periodic_reviews        one review of one plan for one due date: Open -> Completed (QA e-signature PERIODIC_REVIEW) or Cancelled. The
--                           evidence (a JSON snapshot of the records reviewed, with its SHA-256) is generated by the server when the review is
--                           opened and never edited; findings and the conclusion are recorded by the reviewer. A Completed review cannot be
--                           changed or deleted (trigger).
--   retention_policies      per record class, the number of years to keep. No row, or retention_years NULL, means keep indefinitely: the
--                           conservative default. The number is a decision of the organisation (QA e-signature RETENTION_POLICY).
--   legal_holds             a hold on a record class (or on one record of it). While one is Active, nothing of that class can be flagged
--                           for purge (retention_flags trigger). Placing and releasing are e-signed (LEGAL_HOLD).
--   retention_flags         "this archived record has outlived its retention and may be considered for disposal". It is ONLY a flag: the
--                           application ships no purge function and nothing here deletes a GxP record.
--   archive_bundles         the register of export bundles (a folder of open-format files with a SHA-256 manifest). Built -> Archived by a
--                           QA e-signature (ARCHIVE_DECISION) that is bound to the manifest hash.
--   archived_records        the sidecar that marks records as archived: written once, in the transaction of the QA decision, never changed.
--                           The core tables are not altered; triggers refuse an UPDATE or DELETE of an archived sample, result, batch,
--                           batch release or CoA (the HTTP guard answers 423 first; the trigger is the backstop for every other path).
--   signature_meanings      + PERIODIC_REVIEW, ARCHIVE_DECISION, RETENTION_POLICY, LEGAL_HOLD (QA only).
--   permissions             + periodic.view, periodic.manage, periodic.sign, archive.view, archive.manage, retention.manage (330-335).
--
-- The constants are written only under the migration runner (WHERE EXISTS schema_migrations), because a restore replays this file into an
-- EMPTY database.

CREATE TABLE "periodic_review_plans" (
	"id" text PRIMARY KEY NOT NULL,
	"kind" text NOT NULL,
	"subject_id" text NOT NULL,
	"title" text NOT NULL,
	"interval_months" integer NOT NULL,
	"next_due_date" text NOT NULL,
	"checklist" jsonb DEFAULT '[]'::jsonb NOT NULL,
	"status" text DEFAULT 'Active' NOT NULL,
	"created_by" text NOT NULL,
	"created_at" timestamp with time zone DEFAULT now() NOT NULL,
	"version" integer DEFAULT 1 NOT NULL,
	CONSTRAINT "periodic_review_plans_kind_check" CHECK ("periodic_review_plans"."kind" IN ('user_access', 'instrument', 'specification', 'method', 'document', 'module', 'system')),
	CONSTRAINT "periodic_review_plans_status_check" CHECK ("periodic_review_plans"."status" IN ('Active', 'Retired')),
	CONSTRAINT "periodic_review_plans_interval_check" CHECK ("periodic_review_plans"."interval_months" BETWEEN 1 AND 120),
	CONSTRAINT "periodic_review_plans_due_check" CHECK ("periodic_review_plans"."next_due_date" ~ '^\d{4}-\d{2}-\d{2}$')
);

CREATE TABLE "periodic_reviews" (
	"id" text PRIMARY KEY NOT NULL,
	"plan_id" text NOT NULL,
	"kind" text NOT NULL,
	"subject_id" text NOT NULL,
	"title" text NOT NULL,
	"due_date" text NOT NULL,
	"status" text DEFAULT 'Open' NOT NULL,
	"evidence" jsonb NOT NULL,
	"evidence_sha256" text NOT NULL,
	"evidence_generated_at" timestamp with time zone NOT NULL,
	"checklist" jsonb DEFAULT '[]'::jsonb NOT NULL,
	"findings" jsonb DEFAULT '[]'::jsonb NOT NULL,
	"conclusion" text,
	"summary" text,
	"opened_by" text NOT NULL,
	"opened_at" timestamp with time zone DEFAULT now() NOT NULL,
	"completed_by" text,
	"completed_at" timestamp with time zone,
	"version" integer DEFAULT 1 NOT NULL,
	CONSTRAINT "periodic_reviews_status_check" CHECK ("periodic_reviews"."status" IN ('Open', 'Completed', 'Cancelled')),
	CONSTRAINT "periodic_reviews_conclusion_check" CHECK ("periodic_reviews"."conclusion" IS NULL OR "periodic_reviews"."conclusion" IN ('Satisfactory', 'SatisfactoryWithActions', 'Unsatisfactory')),
	CONSTRAINT "periodic_reviews_completed_check" CHECK ("periodic_reviews"."status" <> 'Completed' OR ("periodic_reviews"."conclusion" IS NOT NULL AND "periodic_reviews"."completed_by" IS NOT NULL AND "periodic_reviews"."completed_at" IS NOT NULL))
);

CREATE TABLE "retention_policies" (
	"record_class" text PRIMARY KEY NOT NULL,
	"retention_years" integer,
	"basis" text NOT NULL,
	"updated_by" text NOT NULL,
	"updated_at" timestamp with time zone DEFAULT now() NOT NULL,
	"version" integer DEFAULT 1 NOT NULL,
	CONSTRAINT "retention_policies_years_check" CHECK ("retention_policies"."retention_years" IS NULL OR "retention_policies"."retention_years" BETWEEN 1 AND 100),
	CONSTRAINT "retention_policies_basis_check" CHECK (length(btrim("retention_policies"."basis")) >= 5)
);

CREATE TABLE "legal_holds" (
	"id" text PRIMARY KEY NOT NULL,
	"record_class" text NOT NULL,
	"scope_ref" text,
	"reason" text NOT NULL,
	"status" text DEFAULT 'Active' NOT NULL,
	"placed_by" text NOT NULL,
	"placed_at" timestamp with time zone DEFAULT now() NOT NULL,
	"released_by" text,
	"released_at" timestamp with time zone,
	"release_reason" text,
	"version" integer DEFAULT 1 NOT NULL,
	CONSTRAINT "legal_holds_status_check" CHECK ("legal_holds"."status" IN ('Active', 'Released')),
	CONSTRAINT "legal_holds_reason_check" CHECK (length(btrim("legal_holds"."reason")) >= 5),
	CONSTRAINT "legal_holds_released_check" CHECK ("legal_holds"."status" = 'Active' OR ("legal_holds"."released_by" IS NOT NULL AND "legal_holds"."released_at" IS NOT NULL AND "legal_holds"."release_reason" IS NOT NULL))
);

CREATE TABLE "archive_bundles" (
	"id" text PRIMARY KEY NOT NULL,
	"kind" text DEFAULT 'batch' NOT NULL,
	"subject_id" text NOT NULL,
	"subject_label" text NOT NULL,
	"dir_name" text NOT NULL,
	"manifest_sha256" text NOT NULL,
	"file_count" integer NOT NULL,
	"bytes" bigint NOT NULL,
	"record_counts" jsonb NOT NULL,
	"status" text DEFAULT 'Built' NOT NULL,
	"built_by" text NOT NULL,
	"built_at" timestamp with time zone DEFAULT now() NOT NULL,
	"last_verified_at" timestamp with time zone,
	"last_verified_ok" boolean,
	"decided_by" text,
	"decided_at" timestamp with time zone,
	"version" integer DEFAULT 1 NOT NULL,
	CONSTRAINT "archive_bundles_kind_check" CHECK ("archive_bundles"."kind" IN ('batch')),
	CONSTRAINT "archive_bundles_status_check" CHECK ("archive_bundles"."status" IN ('Built', 'Archived')),
	CONSTRAINT "archive_bundles_manifest_check" CHECK ("archive_bundles"."manifest_sha256" ~ '^[0-9a-f]{64}$'),
	CONSTRAINT "archive_bundles_archived_check" CHECK ("archive_bundles"."status" <> 'Archived' OR ("archive_bundles"."decided_by" IS NOT NULL AND "archive_bundles"."decided_at" IS NOT NULL))
);

CREATE TABLE "archived_records" (
	"id" text PRIMARY KEY NOT NULL,
	"entity_type" text NOT NULL,
	"entity_id" text NOT NULL,
	"bundle_id" text NOT NULL,
	"archived_by" text NOT NULL,
	"archived_at" timestamp with time zone DEFAULT now() NOT NULL
);

CREATE TABLE "retention_flags" (
	"id" text PRIMARY KEY NOT NULL,
	"record_class" text NOT NULL,
	"entity_type" text NOT NULL,
	"entity_id" text NOT NULL,
	"reason" text NOT NULL,
	"status" text DEFAULT 'Flagged' NOT NULL,
	"flagged_by" text NOT NULL,
	"flagged_at" timestamp with time zone DEFAULT now() NOT NULL,
	"withdrawn_by" text,
	"withdrawn_at" timestamp with time zone,
	"version" integer DEFAULT 1 NOT NULL,
	CONSTRAINT "retention_flags_status_check" CHECK ("retention_flags"."status" IN ('Flagged', 'Withdrawn'))
);

ALTER TABLE "periodic_review_plans" ADD CONSTRAINT "periodic_review_plans_created_by_users_id_fk" FOREIGN KEY ("created_by") REFERENCES "public"."users"("id") ON DELETE no action ON UPDATE no action;
ALTER TABLE "periodic_reviews" ADD CONSTRAINT "periodic_reviews_plan_id_periodic_review_plans_id_fk" FOREIGN KEY ("plan_id") REFERENCES "public"."periodic_review_plans"("id") ON DELETE no action ON UPDATE no action;
ALTER TABLE "periodic_reviews" ADD CONSTRAINT "periodic_reviews_opened_by_users_id_fk" FOREIGN KEY ("opened_by") REFERENCES "public"."users"("id") ON DELETE no action ON UPDATE no action;
ALTER TABLE "periodic_reviews" ADD CONSTRAINT "periodic_reviews_completed_by_users_id_fk" FOREIGN KEY ("completed_by") REFERENCES "public"."users"("id") ON DELETE no action ON UPDATE no action;
